"let installed='', entries=[];\n"
"async function get(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);return r.json();}\n"
"async function loadInstalled(){try{let d=await get('/api/info');installed=d.version||'';el('installed').textContent='Installed: '+(installed||'Unknown');el('ota-status').textContent='OTA: '+(d.ota_result||'idle');}catch(e){installed='';el('installed').textContent='Could not read installed version. Updates disabled.';}}\n"
"function versionParts(v){\n"
" const m=String(v||'').trim().replace(/^v/i,'').match(/^(\\d+)\\.(\\d+)(?:\\.(\\d+))?(?:[-.](alpha|beta|rc)(?:[.-]?(\\d+))?)?$/i);\n"
" if(!m)return null;\n"
" const stage=(m[4]||'').toLowerCase(),rank=stage===''?4:stage==='rc'?3:stage==='beta'?2:1;\n"
" return [Number(m[1]),Number(m[2]),Number(m[3]||0),rank,Number(m[5]||0)];\n"
"}\n"
"function versionCompare(a,b){\n"
" const x=versionParts(a),y=versionParts(b);if(!x||!y)return 0;\n"
" for(let i=0;i<x.length;i++)if(x[i]!==y[i])return x[i]>y[i]?1:-1;\n"
" return 0;\n"
"}\n"
"/* At most Old / Current / New, relative to the installed version.\n"
"   Release metadata is data, never authorization for a downgrade. */\n"
"function selectFirmwareRows(available,current){\n"
" const valid=available.filter(b=>b.version&&b.url&&versionParts(b.version));\n"
" valid.sort((a,b)=>versionCompare(b.version,a.version)||((b.publishedAt||0)-(a.publishedAt||0))||((b.channel==='Alpha'?1:0)-(a.channel==='Alpha'?1:0)));\n"
" const seen=new Set();\n"
" const unique=valid.filter(b=>{const key=versionParts(b.version).join(':');if(seen.has(key))return false;seen.add(key);return true});\n"
" const rows=[];\n"
" const known=!!versionParts(current);\n"
" const old=known?unique.find(b=>versionCompare(b.version,current)<0):null;\n"
" const currentImage=known?unique.find(b=>b.version===current):null;\n const newer=known?unique.find(b=>versionCompare(b.version,current)>0):null;\n"
" if(old)rows.push({...old,kind:'Old',label:'Old — '+old.version+' (previous published)',disabled:true});\n"
" rows.push({kind:'Current',version:current||'Unknown',url:currentImage?currentImage.url:null,label:'Current — '+(current||'Unknown')+(currentImage?' (reinstall available)':' (image unavailable)'),disabled:!currentImage});\n"
" if(newer)rows.push({...newer,kind:'New',label:'New — '+newer.version+' (latest verified OTA)',disabled:false});\n"
" return rows;\n"
"}\n"
"function selectedInstall(){\n"
" const i=Number(el('builds').value),b=Number.isInteger(i)?entries[i]:null;\n"
" if(!b||b.disabled||!b.url||!versionParts(installed))return null;\n if(b.kind==='Current'&&b.version===installed)return b;\n if(b.kind==='New'&&versionCompare(b.version,installed)>0)return b;\n return null;\n"
"}\n"
"async function loadBuilds(refresh=false){\n"
" const selector=el('builds'),button=el('refresh-builds');\n let checkedAtLeastOneSource=false;\n"
" const lastUrl=selector.value===''?null:entries[Number(selector.value)]?.url;\n"
" button.disabled=true;selector.disabled=true;el('install').disabled=true;\n"
" el('catalog-status').textContent=refresh?'Refreshing published versions from GitHub…':'Checking published versions…';\n"
" entries=[];\n"
" const base='https://skiiirt1983.github.io/LyricFlash/beta/';\n"
" const cacheBuster='?r='+Date.now();\n"
" /* Successful private-channel alpha builds are GitHub prereleases, not only\n"
"    GitHub Pages stable releases. GitHub's public REST API is CORS-accessible,\n"
"    and every downloaded OTA is revalidated by ESP-IDF on the device. */\n"
" try{\n"
" const releases=await get('https://api.github.com/repos/skiiirt1983/LyricFlash/releases?per_page=40&'+cacheBuster.slice(1));\n"
" if(!Array.isArray(releases))throw Error('Invalid GitHub releases response');\n checkedAtLeastOneSource=true;\n"
" for(const release of releases){\n"
"   if(release.draft||!release.prerelease||!/^alpha-build-[a-f0-9]{12}$/.test(release.tag_name||''))continue;\n"
"   const asset=(release.assets||[]).find(a=>a.name==='lyricflash-ota.bin'&&a.size>0&&a.size<=5242880);\n"
"   const match=/(?:^|\\n)LyricFlash-OTA-Version:\\s*([0-9][a-z0-9._-]*)/i.exec(release.body||'');\n"
"   if(!asset||!match)continue;\n"
"   const prefix='https://github.com/skiiirt1983/LyricFlash/releases/download/'+release.tag_name+'/';\n"
"   if(asset.browser_download_url!==prefix+'lyricflash-ota.bin')continue;\n"
"   /* A verified, immutable raw-GitHub asset avoids release redirect chains. */\n"
"   const notePrefix='LyricFlash-OTA-Direct: ';\n"
"   const direct=(release.body||'').split('\\n').find(line=>line.startsWith(notePrefix));\n"
"   const expected='https://raw.githubusercontent.com/skiiirt1983/LyricFlash/alpha-ota/releases/'+release.tag_name+'/lyricflash-ota.bin';\n"
"   const url=direct&&direct.slice(notePrefix.length).trim()===expected?expected:asset.browser_download_url;\n"
"   entries.push({version:match[1],url,label:'ALPHA '+match[1]+' · build '+release.tag_name.slice(-8),channel:'Alpha',publishedAt:Date.parse(release.published_at||'')||0});\n"
" }\n"
" }catch(e){/* Fall back to optional Pages sources. Technical errors are not shown to the user. */}\n"
" try{\n"
" const c=await get(base+'catalog.json'+cacheBuster);\n"
" if(c.product!=='LyricFlash'||c.chipFamily!=='ESP32-S3'||!Array.isArray(c.builds))throw Error('Invalid firmware catalog');\n checkedAtLeastOneSource=true;\n"
" for(const b of c.builds){\n"
" if(!b.version||!/^https:\\/\\/skiiirt1983\\.github\\.io\\/LyricFlash\\/beta\\/firmware\\//.test(b.url))continue;\n"
" entries.push({version:b.version,url:b.url,label:b.label||b.version,channel:b.channel||'Beta'});\n"
" }\n"
" }catch(e){/* The Pages catalog is optional, especially for private alpha builds. */}\n"
" try{\n"
" const m=await get(base+'manifest.json'+cacheBuster);\n if(m&&typeof m==='object'&&(m.version||m.builds))checkedAtLeastOneSource=true;\n"
" if(m.version&&m.builds?.some(b=>b.chipFamily==='ESP32-S3')&&!entries.some(b=>b.version===m.version))\n"
" entries.push({version:m.version,url:base+'firmware/lyricflash-ota.bin',label:'BETA '+m.version,channel:'Beta'});\n"
" }catch(e){/* Manifest is an optional secondary source. */}\n"
" /* Collapse multiple metadata sources to the nearest old and latest new.\n"
"    Current comes from the device itself, never the release catalog. */\n"
" entries=selectFirmwareRows(entries,installed);\n"
" selector.replaceChildren();\n"
" for(let i=0;i<entries.length;i++){\n"
"   const b=entries[i],option=new Option(b.label,String(i));\n"
"   option.disabled=!!b.disabled;\n"
"   selector.add(option);\n"
" }\n"
" const previousChoice=entries.findIndex(b=>b.url===lastUrl&&!b.disabled&&b.kind!=='Old');\n"
" const currentIndex=entries.findIndex(b=>b.kind==='Current');\n"
" selector.value=String(previousChoice>=0?previousChoice:currentIndex);\n"
" const hasInstallable=entries.some(b=>!b.disabled&&!!b.url);\n"
" selector.disabled=!hasInstallable;\n"
" const choice=selectedInstall();el('install').disabled=!choice;\n el('install').textContent=choice&&choice.kind==='Current'?'Reinstall current firmware':choice&&choice.kind==='New'?'Install new firmware':'Install selected OTA version';\n"
" const newBuild=entries.find(b=>b.kind==='New');\n"
" el('build-info').textContent=hasInstallable?'Select Current to reinstall the exact published image, or New to update. Old remains disabled. Reinstalling preserves saved Wi-Fi and settings.':'No installable verified image found. Current remains installed; Old is reference-only.';\n"
" el('catalog-status').textContent=(refresh?'Update check complete. ':'')+\n"
"   (newBuild?'New firmware available: '+newBuild.version+'. ':checkedAtLeastOneSource?'No newer firmware available. ':'Unable to check for updates. Check your Internet connection and try again. ')+\n"
"   /* Keep optional HTTP codes out of the normal firmware update status. */\n"
"   new Date().toLocaleTimeString();\n"
" button.disabled=false;\n"
"}\n"
"el('refresh-builds').onclick=async()=>{await loadInstalled();await loadBuilds(true)};\n"
"el('builds').onchange=()=>{\n"
" const b=selectedInstall();el('install').disabled=!b;\n el('install').textContent=b&&b.kind==='Current'?'Reinstall current firmware':b&&b.kind==='New'?'Install new firmware':'Install selected OTA version';\n"
" if(!b)info('Select Current (with a verified published image) to reinstall, or New to update.');\n"
"};\n"
"el('install').onclick=async()=>{\n"
" const b=selectedInstall();\n"
" if(!b)return info('Only a verified Current reinstall or a New update can be installed. Old versions remain disabled.');\n"
" if(!confirm((b.kind==='Current'?'Reinstall the currently installed ':'Install the newer ')+b.version+' firmware? Device downloads, validates and reboots. Saved Wi-Fi and settings remain intact; a reinstall is NOT a factory reset.'))return;\n"
" try{el('install').disabled=true;info('Starting download on device…');\n"
" let r=await fetch('/api/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:b.url,version:b.version})});\n"
" const text=await r.text();if(!r.ok)throw Error(text);info(text);pollProgress();\n"
" }catch(e){info('Could not start firmware update: '+e.message);el('install').disabled=!selectedInstall()}\n"
"};\n"
"async function pollProgress(){for(let i=0;i<300;i++){await new Promise(r=>setTimeout(r,1000));try{\n"
" const d=await get('/api/info');const result=d.ota_result||'unknown';\n"
" info('Status: '+result+(d.ota_total?' · '+Math.round(100*(d.ota_received||0)/d.ota_total)+'%':'')+\n"
"      (d.ota_detail?'\\n'+d.ota_detail:'')+\n"
"      (d.ota_http_status?' · HTTP '+d.ota_http_status:'')+\n"
"      (d.ota_error_code?' · ESP '+d.ota_error_code:'')+\n"
"      (d.ota_tls_code?' · TLS '+d.ota_tls_code:'')+\n"
"      (d.ota_tls_flags?' · Certificate '+d.ota_tls_flags:'')+\n"
"      (d.ota_socket_errno?' · Socket '+d.ota_socket_errno:''));\n"
"\n"
" if(result==='verified_rebooting'||result==='complete'){info('Firmware verified; device restarting…');return}\n"
" if(result.endsWith('_failed')||['bad_version','invalid_url','bad_size','no_internet','time_unsynced','download_failed'].includes(result)){el('install').disabled=!selectedInstall();return}\n"
" }catch(e){info('Device connection interrupted. It may be restarting; reconnect to confirm version.');return}}}\n"
"el('upload').onclick=()=>{\n"
" const f=el('bin').files[0];if(!f)return el('upload-status').textContent='Select an application-only OTA image';\n"
" if(!confirm('Upload '+f.name+' as OTA firmware? Wi-Fi settings remain saved.'))return;\n"
" const button=el('upload'),xhr=new XMLHttpRequest();button.disabled=true;\n"
" xhr.open('POST','/update');xhr.timeout=180000;xhr.setRequestHeader('Content-Type','application/octet-stream');\n"
" xhr.upload.onprogress=e=>el('upload-status').textContent=e.lengthComputable?'Uploading '+Math.round(e.loaded/e.total*100)+'%':'Uploading…';\n"
" xhr.onload=()=>{button.disabled=false;el('upload-status').textContent=xhr.status>=200&&xhr.status<300?xhr.responseText:'Upload rejected: '+xhr.responseText};\n"
" xhr.onerror=()=>{button.disabled=false;el('upload-status').textContent='Connection error'};\n"
" xhr.ontimeout=()=>{button.disabled=false;el('upload-status').textContent='Upload timed out'};\n"
" xhr.send(f);\n"
"};\n"
"loadInstalled().then(loadBuilds);\n"
"</script></body></html>\n"
"\n"
"\n"
"\n"
;
